 WHERE 1=1
AND (r.repair_no LIKE CONCAT('%',#{keyword},'%') OR a.asset_code LIKE CONCAT('%',#{keyword},'%') OR a.asset_name LIKE CONCAT('%',#{keyword},'%'))
AND r.status=#{status}
AND r.asset_dept_id=#{deptId}
AND a.category_id=#{categoryId}
AND a.location_id=#{locationId}
AND r.fault_type=#{faultType}
AND p.nick_name LIKE CONCAT('%',#{repairer},'%')
AND r.report_time >= #{beginTime}
AND r.report_time <= #{endTime}
AND (1=1
  1=0
  OR r.asset_dept_id IN
    #{d}

  OR r.reporter_user_id=#{selfUserId} OR r.repairer_user_id=#{selfUserId}
)
