mapper.update:
UPDATE ca_repair SET status=#{status},update_by=#{actor},update_time=NOW(3)
,accept_user_id=#{userId},accept_time=NOW(3),accept_opinion=#{opinion}
,repairer_user_id=#{repairer},assign_time=NOW(3)
WHERE repair_id=#{id} AND status=#{expected}

UPDATE ca_repair SET status=#{status},update_by=#{actor},update_time=NOW(3)
,verify_user_id=#{userId},verify_time=NOW(3),verify_opinion=#{opinion}
WHERE repair_id=#{id} AND status='3'
